(()=>{'use strict';const $=s=>document.querySelector(s),labels={replay:'Replay 视频',radar:'Radar 轨迹',scoredeck:'赛程 / 积分 / 战绩',nameA:'A 队全名',nameB:'B 队全名',shortA:'A 队简称',shortB:'B 队简称',logoA:'A 队标识',logoB:'B 队标识',scoreA:'A 小局比分',scoreB:'B 小局比分',mapName:'地图名称',mapIcon:'地图图标',bp:'地图 BP',title:'标题',round:'轮次',timer:'倒计时',text:'自定义文字',image:'图片',video:'视频'};
let mode='half',snapshot,draft,selected='',dirty=false,saving=false;const notice=t=>$('#notice').textContent=t,p=()=>draft?.[mode],element=()=>p()?.elements.find(e=>e.id===selected);
for(const [v,t]of Object.entries(labels))$('#type').append(new Option(t,v));
function preview(){if(!snapshot||!draft)return;$('#preview').contentWindow?.postMessage({type:'scoredeck-halftime-preview',snapshot:{...snapshot,mode,customLayout:true,layouts:draft}},location.origin);}
function change(){dirty=true;notice('有未保存修改');preview();}
function properties(){const e=element();$('#fields').hidden=!e;$('#empty-selection').hidden=!!e;if(!e)return;$('#element-name').textContent=labels[e.type];for(const el of document.querySelectorAll('[data-field]')){if(el.type==='checkbox')el.checked=!!e[el.dataset.field];else el.value=e[el.dataset.field]??'';}}
function boxes(){const overlay=$('#overlay');overlay.replaceChildren();for(const e of p().elements){const box=document.createElement('div');box.className='box'+(e.id===selected?' selected':'');box.dataset.id=e.id;Object.assign(box.style,{left:e.x/19.2+'%',top:e.y/10.8+'%',width:e.w/19.2+'%',height:e.h/10.8+'%'});const title=document.createElement('span');title.textContent=labels[e.type];const handle=document.createElement('i');handle.className='handle';box.append(title,handle);overlay.append(box);box.onpointerdown=event=>{event.preventDefault();selected=e.id;layers();properties();overlay.querySelectorAll('.box').forEach(b=>b.classList.toggle('selected',b.dataset.id===selected));const start={x:event.clientX,y:event.clientY,...e},scale=$('#canvas').clientWidth/1920,resize=event.target===handle;box.setPointerCapture(event.pointerId);box.onpointermove=ev=>{const dx=(ev.clientX-start.x)/scale,dy=(ev.clientY-start.y)/scale;if(resize){e.w=Math.round(Math.max(20,Math.min(1920-e.x,start.w+dx)));e.h=Math.round(Math.max(20,Math.min(1080-e.y,start.h+dy)));}else{e.x=Math.round(Math.max(0,Math.min(1920-e.w,start.x0+dx)));e.y=Math.round(Math.max(0,Math.min(1080-e.h,start.y0+dy)));}Object.assign(box.style,{left:e.x/19.2+'%',top:e.y/10.8+'%',width:e.w/19.2+'%',height:e.h/10.8+'%'});properties();change();};start.x0=e.x;start.y0=e.y;start.x=event.clientX;start.y=event.clientY;box.onpointerup=()=>{box.onpointermove=null;};};}}
function layers(){$('#layers').replaceChildren(...p().elements.map(e=>{const b=document.createElement('button');b.textContent=labels[e.type];b.className=e.id===selected?'selected':'';b.onclick=()=>{selected=e.id;layers();boxes();properties();};return b;}));}
function render(){$('#mode-name').textContent=mode==='half'?'半场精选':'全场精选';document.querySelectorAll('[data-mode]').forEach(b=>b.classList.toggle('active',b.dataset.mode===mode));$('#background').value=p().background;$('#background-image').value=p().backgroundImage||'';$('#transparent').checked=p().transparent;$('#full-auto').checked=draft.fullAuto;layers();boxes();properties();preview();}
async function load(){snapshot=await(await fetch('/api/highlights?mode='+mode,{cache:'no-store'})).json();draft=structuredClone(snapshot.layouts);dirty=false;selected='';render();notice('已载入');}
async function save(){if(saving||!draft)return;saving=true;$('#save').disabled=true;try{snapshot=await SDClient.request('/api/highlights',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({layouts:draft,expectedRevision:draft.revision,mode})});draft=structuredClone(snapshot.layouts);dirty=false;render();notice('半场和全场画面已保存');return true;}catch(e){notice(e.message);return false;}finally{saving=false;$('#save').disabled=false;}}
$('#save').onclick=save;$('#reload').onclick=()=>{if(!dirty||confirm('放弃未保存的画面修改？'))load().catch(e=>notice(e.message));};document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;selected='';render();});
$('#add').onclick=()=>{if(p().elements.length>=60)return notice('最多 60 个元素');const type=$('#type').value,e={id:crypto.randomUUID(),type,x:100,y:100,w:['replay','video','scoredeck'].includes(type)?960:400,h:['replay','video','scoredeck'].includes(type)?540:['radar','image','mapIcon','bp'].includes(type)?240:90,fontSize:48,color:'#ffffff',opacity:1,text:'',source:'',scene:'schedule',fit:'contain',muted:false,loop:true,half:1,layer:'all',fade:3,showPlayers:true,speed:1};p().elements.push(e);selected=e.id;render();change();};
$('#remove').onclick=()=>{p().elements=p().elements.filter(e=>e.id!==selected);selected='';render();change();};$('#duplicate').onclick=()=>{const e=element();if(!e||p().elements.length>=60)return;const copy={...e,id:crypto.randomUUID(),x:Math.min(1920-e.w,e.x+20),y:Math.min(1080-e.h,e.y+20)};p().elements.push(copy);selected=copy.id;render();change();};
for(const [id,delta]of [['up',1],['down',-1]])$('#'+id).onclick=()=>{const a=p().elements,i=a.findIndex(e=>e.id===selected),j=i+delta;if(i<0||j<0||j>=a.length)return;[a[i],a[j]]=[a[j],a[i]];render();change();};
$('#empty').onclick=()=>{if(confirm('清空当前画面的全部元素？')){p().elements=[];selected='';render();change();}};
for(const el of document.querySelectorAll('[data-field]'))el.oninput=()=>{const e=element();if(!e)return;e[el.dataset.field]=el.type==='checkbox'?el.checked:['number','range'].includes(el.type)?Number(el.value):el.value;boxes();change();};
$('#background').oninput=()=>{p().background=$('#background').value;change();};$('#transparent').oninput=()=>{p().transparent=$('#transparent').checked;change();};$('#background-image').oninput=()=>{p().backgroundImage=$('#background-image').value;change();};$('#full-auto').oninput=()=>{draft.fullAuto=$('#full-auto').checked;change();};
for(const id of ['background-file','element-file'])$('#'+id).onchange=async ev=>{const f=ev.target.files?.[0];if(!f)return;const target=id==='element-file'?element():null;try{const result=await SDClient.request('/api/halftime/media',{method:'POST',headers:{'Content-Type':f.type},body:f});if(target)target.source=result.url;else p().backgroundImage=result.url;render();change();}catch(e){notice(e.message);}ev.target.value='';};
$('#copy').onclick=async()=>{const u=location.origin+'/output/halftime-auto';try{await navigator.clipboard.writeText(u);notice('已复制：'+u);}catch{notice(u);}};
async function program(action){if(dirty&&!await save())return;try{snapshot=await(await fetch('/api/highlights?mode='+mode)).json();await SDClient.request('/api/halftime/program',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action,mode,expectedRevision:snapshot.config.revision})});notice(action==='show'?'已播出':'已结束播出');}catch(e){notice(e.message);}}
$('#play').onclick=()=>program('show');$('#hide').onclick=()=>program('hide');$('#preview').onload=preview;addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});addEventListener('message',e=>{if(e.origin===location.origin&&e.source===$('#preview').contentWindow&&e.data?.type==='scoredeck-halftime-ready')preview();});
load().catch(e=>notice(e.message));setInterval(preview,2000);
})();
